package co.edu.uts.web;import co.edu.uts.data.Database;import jakarta.servlet.http.*;import java.util.*;import org.mindrot.jbcrypt.BCrypt;public class AuthBean{private HttpServletRequest r;private String error;public void setRequest(HttpServletRequest x){r=x;Database.init();}public String getError(){return error;}public String process(){if(!"POST".equals(r.getMethod()))return null;try{Map<String,Object>u=Database.one("SELECT * FROM usuario WHERE correo=? AND activo=TRUE",r.getParameter("correo"));if(u==null||!BCrypt.checkpw(r.getParameter("contrasena"),""+u.get("contrasena"))){error="Credenciales inválidas.";return null;}r.getSession().invalidate();r.getSession(true).setAttribute("user",u);return r.getContextPath()+"/inicio.jsp";}catch(Exception e){error="Error de conexión.";return null;}}public String logout(){r.getSession().invalidate();return r.getContextPath()+"/login.jsp";}}